const D=window.GTD_DATA; const KEY='gtd_state_final_local_v1'; const BACKUP_MAGIC='GTD-JOURNEY'; const BACKUP_VERSION=1;
const LEGACY_KEYS=['gtd_state_v20','gtd_state_v10','gtd_state_v09'];
function loadInitialState(){let raw=localStorage.getItem(KEY);if(!raw){for(const k of LEGACY_KEYS){raw=localStorage.getItem(k);if(raw)break}}try{return raw?JSON.parse(raw):null}catch(e){return null}}
let state=loadInitialState()||{profile:{},checkup:{},days:{},journeyNotes:{},logs:[],parentChecks:[],savedWatch:[],savedActivities:[],journeyStartedAt:null,maintenance:{weeklyNote:''},meta:{familyId:(globalThis.crypto&&crypto.randomUUID?crypto.randomUUID():String(Date.now())),lastBackupAt:null,deviceAcknowledged:false}};
state.profile=state.profile||{};state.checkup=state.checkup||{};state.days=state.days||{};state.journeyNotes=state.journeyNotes||{};state.logs=state.logs||[];state.parentChecks=state.parentChecks||[];state.savedWatch=state.savedWatch||[];state.savedActivities=state.savedActivities||[];state.maintenance=state.maintenance||{};state.maintenance.weeklyNote=state.maintenance.weeklyNote||'';state.maintenance.weeklyReviews=state.maintenance.weeklyReviews||[];state.maintenance.nextExperiment=state.maintenance.nextExperiment||'';state.meta=state.meta||{familyId:(globalThis.crypto&&crypto.randomUUID?crypto.randomUUID():String(Date.now())),lastBackupAt:null,deviceAcknowledged:false};
const app=document.getElementById('app');
function toast(message,type='ok'){let el=document.getElementById('gtd-toast');if(!el){el=document.createElement('div');el.id='gtd-toast';document.body.appendChild(el)}el.className='gtd-toast '+type;el.textContent=message;requestAnimationFrame(()=>el.classList.add('show'));clearTimeout(window.__gtdToastTimer);window.__gtdToastTimer=setTimeout(()=>el.classList.remove('show'),2800)}
function formatDateTimeID(iso){if(!iso)return 'Belum pernah';return new Date(iso).toLocaleString('id-ID',{day:'numeric',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'});}
function save(){state.meta=state.meta||{};if(!state.meta.familyId)state.meta.familyId=(globalThis.crypto&&crypto.randomUUID?crypto.randomUUID():String(Date.now()));localStorage.setItem(KEY,JSON.stringify(state));}
function esc(s=''){return String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));}
function ageBand(age){if(age<=4)return '3-5'; if(age<=7)return '5-7'; return '8-10';}
function profileReady(){return state.profile.name && state.profile.age;}
function nav(view){document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view)); render(view);}
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>nav(b.dataset.view));
document.getElementById('reportBtn').onclick=()=>printReport(); document.getElementById('saveJourneyBtn').onclick=()=>backup();
function setProfile(form){const fd=new FormData(form);state.profile={name:fd.get('name').trim(),age:+fd.get('age'),caregiver:fd.get('caregiver').trim()||'Orang tua'};save();nav('checkup');setTimeout(()=>toast('Profil keluarga tersimpan. Lanjut isi Digital Check-Up.'),0);}
function saveCheckup(form){const fd=new FormData(form);state.checkup={baseline:+fd.get('baseline')||0,target:+fd.get('target')||0,goal:fd.get('goal'),hard:fd.get('hard'),anchor:fd.get('anchor'),fav:fd.get('fav'),parentHabit:fd.get('parentHabit')};save();nav('home');setTimeout(()=>toast('✓ Family Digital Plan tersimpan.'),0);}
function makePlan(){const c=state.checkup,p=state.profile; if(!c.goal)return 'Lengkapi Digital Check-Up dulu.'; let focus={conflict:'transisi dan konsistensi aturan',duration:'keseimbangan durasi tanpa target ekstrem',content:'kualitas dan pemilihan konten',sleep:'rutinitas bebas layar menjelang tidur',connection:'ruang keluarga tanpa distraksi'}[c.goal]||'kebiasaan digital'; return `Fokus awal untuk ${p.name}: ${focus}. Titik sulit utama: ${c.hard||'-'}. Waktu Bebas Layar Pertama: ${c.anchor||'-'}. Target durasi adalah keputusan keluarga dan dapat direvisi berdasarkan log, bukan diagnosis otomatis.`}
function completedDays(){return Object.values(state.days).filter(Boolean).length;}
function blueprintReady(){return !!state.journeyStartedAt && elapsedProgramDays()>=14;}
function startJourney(){if(state.journeyStartedAt){renderJourney();return;}state.journeyStartedAt=new Date().toISOString();save();renderJourney();setTimeout(()=>toast('🎉 Program dimulai. Hari 1 sudah terbuka.'),0);}
function elapsedProgramDays(){if(!state.journeyStartedAt)return 0;const start=new Date(state.journeyStartedAt);const now=new Date();start.setHours(0,0,0,0);now.setHours(0,0,0,0);return Math.max(1,Math.floor((now-start)/86400000)+1);} function currentProgramDay(){return state.journeyStartedAt?Math.min(14,elapsedProgramDays()):0;}
function dayUnlocked(n){return !!state.journeyStartedAt && n<=currentProgramDay();}
function saveDay(n){const note=(document.getElementById('daynote'+n)?.value||'').trim();state.journeyNotes[n]=note;state.days[n]=true;save();renderJourney();setTimeout(()=>toast(`✓ Hari ${n} tersimpan.`),0);}

const CORE_PRINCIPLES=[
  {id:'steady',icon:'🧭',title:'Tegas tanpa reaktif',short:'Batas jelas, respons tetap tenang.',desc:'Akui perasaan tanpa melepas batas. Instruksi dibuat singkat, konkret, dan tidak mempermalukan.'},
  {id:'bridge',icon:'🌉',title:'Teknologi → pengalaman nyata',short:'Layar selalu punya jembatan keluar.',desc:'Tontonan atau permainan digital disambungkan ke percakapan, gerak, permainan, tugas nyata, atau kebersamaan.'},
  {id:'explore',icon:'🔎',title:'Eksplorasi',short:'Anak diberi ruang mengamati dan mencoba.',desc:'Sesudah layar, anak diajak bertanya, memprediksi, mencoba, mengubah cara, dan menceritakan temuannya.'},
  {id:'capable',icon:'🌱',title:'Rasa mampu',short:'Fokus pada usaha, strategi, dan kontribusi.',desc:'Respons orang tua menyoroti proses dan pilihan anak, bukan hanya hasil sempurna atau kepatuhan.'}
];
function principleById(id){return CORE_PRINCIPLES.find(p=>p.id===id)||CORE_PRINCIPLES[0]}
function principleForDay(n){
  if([5,6,7,12,13].includes(n))return principleById('steady');
  if([4,8,9].includes(n))return principleById('bridge');
  if([1,2,3,10].includes(n))return principleById('explore');
  return principleById('capable');
}
function principlesHTML(compact=false){
  return `<section class="card principles-wrap ${compact?'compact':''}"><div class="row space"><div><div class="label">Kompas Gadget Tanpa Drama</div><h2>4 prinsip yang dipakai di seluruh sistem</h2></div><span class="pill">bukan sekadar halaman teori</span></div><div class="principle-grid">${CORE_PRINCIPLES.map(p=>`<div class="principle-card"><div class="principle-icon">${p.icon}</div><div><b>${p.title}</b><p>${compact?p.short:p.desc}</p></div></div>`).join('')}</div></section>`;
}
function renderHome(){if(!profileReady())return renderOnboard();const done=completedDays();const logs=state.logs;const ready=blueprintReady();const started=!!state.journeyStartedAt;const phase=ready?'Maintenance Mode':'Membangun sistem keluarga';const nextDay=started?Math.min(14,currentProgramDay()):1;app.innerHTML=`<section class="card hero"><span class="pill">${ready?'Blueprint siap':started?'Perjalanan sedang berjalan':'Siap mulai'}</span><h1>Halo, ${esc(state.profile.caregiver)} 👋</h1><p class="sub">${ready?`Family Digital Blueprint untuk ${esc(state.profile.name)} sudah terbentuk. Sekarang aplikasi masuk ke Maintenance Mode.`:`Tujuan kita bukan sekadar mengurangi layar. Selama 14 hari, keluarga akan menguji aturan, transisi, tontonan, dan aktivitas lalu merangkumnya menjadi Family Digital Blueprint.`}</p><div class="row"><button class="primary" onclick="nav('${ready?'blueprint':'journey'}')">${ready?'Lihat Blueprint':started?`Buka Hari ${nextDay}`:'Mulai 14 Hari'}</button><button class="ghost" onclick="nav('checkup')">Edit Family Digital Plan</button>${started?'<button class="ghost" onclick="nav(\'today\')">Buka Today Mode</button>':''}</div></section>${!started?`<section class="card next-step" style="margin-top:16px"><div class="row space"><div><div class="label">Langkah berikutnya</div><h2>Mulai Hari 1: observasi dulu</h2><p>Family Digital Plan sudah siap. Klik <b>Mulai 14 Hari</b>; Hari 1 langsung terbuka hari ini. Tidak perlu menunggu besok atau Hari 14.</p></div><div class="step-badge">1</div></div><button class="primary" onclick="nav('journey')">Mulai sekarang →</button></section>`:`<div class="grid three" style="margin-top:16px"><div class="card"><div class="label">Progress menuju Blueprint</div><div class="metric">${done}/14</div><div class="progress"><div style="width:${done/14*100}%"></div></div></div><div class="card"><div class="label">Check-in tersimpan</div><div class="metric">${logs.length}</div><div class="small">Dipakai untuk melihat pola keluarga</div></div><div class="card"><div class="label">Tontonan tersimpan</div><div class="metric">${state.savedWatch.length}</div><div class="small">Masuk ke Personal Curated Watch List</div></div></div>`}<section class="card" style="margin-top:16px"><div class="row space"><div><div class="label">Output utama</div><h2>Family Digital Blueprint</h2></div><span class="pill ${ready?'ok':'warn'}">${ready?'SIAP':started?'SEDANG DIBANGUN':'BELUM DIMULAI'}</span></div><p>${ready?'Blueprint berisi aturan keluarga, pola 14 hari, strategi transisi, tontonan tersimpan, aktivitas favorit, kebiasaan orang tua, dan rencana 30 hari berikutnya.':'Setiap catatan selama 14 hari mengisi bagian Blueprint. Pada hari kalender ke-14, Blueprint terbuka dari data yang sudah terkumpul—tidak harus sempurna 14/14.'}</p>${ready?'<button class="primary" onclick="nav(\'blueprint\')">Buka Family Digital Blueprint</button>':started?`<div class="notice success"><b>Hari program saat ini: ${currentProgramDay()}.</b> Hari berikutnya terbuka otomatis berdasarkan tanggal mulai.</div>`:'<div class="notice">Mulai dari Digital Check-Up → jalani 14 hari → dapat Blueprint → lanjut Maintenance Mode.</div>'}</section>${principlesHTML(true)}${started?`<section class="card" style="margin-top:16px"><h2>${phase}</h2>${ready?`<div class="grid three"><button class="ghost" onclick="nav('watch')">Cari tontonan berikutnya</button><button class="ghost" onclick="nav('activity')">Pilih aktivitas pengganti</button><button class="ghost" onclick="nav('log')">Catat & review pola</button></div>`:`<p>Untuk hari ini, buka <b>14-Day Reset</b>, isi catatan hari yang terbuka, lalu gunakan Today Mode bila ada sesi layar.</p>`}</section>${patternHTML(true)}`:''}`;}
function renderOnboard(){app.innerHTML=`<section class="card hero"><span class="device-badge">Mulai dalam ±2 menit</span><h1>Bangun rutinitas digital keluarga yang lebih jelas</h1><p class="sub">Gadget Tanpa Drama memandu keluarga selama 14 hari sampai menghasilkan <b>Family Digital Blueprint</b> yang bisa terus dipakai.</p><div class="onboard-flow"><div><b>1</b><span>Isi profil & Digital Check-Up</span></div><div><b>2</b><span>Jalani satu langkah kecil per hari</span></div><div><b>3</b><span>Catat apa yang benar-benar terjadi</span></div><div><b>4</b><span>Hari 14: Blueprint keluarga terbuka</span></div></div><div class="local-note"><b>Privasi:</b> tidak perlu login. Data tersimpan di browser/perangkat ini. Kalau pindah perangkat, gunakan menu <b>Simpan Perjalanan</b> dan <b>Pulihkan Perjalanan</b>.</div><form onsubmit="event.preventDefault();setProfile(this)"><div class="grid two"><div><label>Nama/panggilan anak</label><input name="name" required placeholder="Contoh: Nara"></div><div><label>Usia anak</label><select name="age" required>${[3,4,5,6,7,8,9,10].map(x=>`<option value="${x}">${x} tahun</option>`).join('')}</select></div></div><label>Panggilan caregiver <span class="optional">(opsional)</span></label><input name="caregiver" placeholder="Mama / Ayah / Bunda"><label class="checkline" style="margin-top:14px"><input type="checkbox" required onchange="state.meta=state.meta||{};state.meta.deviceAcknowledged=this.checked;save()"><span>Saya memahami data disimpan di browser/perangkat ini.</span></label><br><button class="primary">Mulai Digital Check-Up →</button></form></section>`;}
function renderCheckup(){if(!profileReady())return renderOnboard();const c=state.checkup;app.innerHTML=`<div class="row space"><div><h1>Family Digital Check-Up</h1><p class="sub">Sekitar 2 menit. Bukan screening klinis; jawaban ini menjadi titik awal Blueprint.</p></div>${c.goal?'<span class="pill ok">Plan sudah tersimpan</span>':''}</div><form class="card" onsubmit="event.preventDefault();saveCheckup(this)"><div class="grid two"><div><label>Rata-rata screen time hiburan saat ini <span class="optional">(menit/hari)</span></label><input type="number" name="baseline" min="0" value="${c.baseline||''}" placeholder="Contoh: 120"></div><div><label>Target keluarga saat ini <span class="optional">(opsional)</span></label><input type="number" name="target" min="0" value="${c.target||''}" placeholder="Boleh dikosongkan dulu"></div><div><label>Tujuan utama</label><select name="goal"><option value="conflict" ${c.goal==='conflict'?'selected':''}>Mengurangi konflik saat berhenti</option><option value="duration" ${c.goal==='duration'?'selected':''}>Mengatur durasi lebih konsisten</option><option value="content" ${c.goal==='content'?'selected':''}>Memilih konten lebih baik</option><option value="sleep" ${c.goal==='sleep'?'selected':''}>Melindungi rutinitas tidur</option><option value="connection" ${c.goal==='connection'?'selected':''}>Lebih banyak waktu keluarga tanpa distraksi</option></select></div><div><label>Momen paling sulit</label><select name="hard"><option ${c.hard==='Saat diminta berhenti'?'selected':''}>Saat diminta berhenti</option><option ${c.hard==='Saat orang tua sibuk'?'selected':''}>Saat orang tua sibuk</option><option ${c.hard==='Menjelang makan'?'selected':''}>Menjelang makan</option><option ${c.hard==='Menjelang tidur'?'selected':''}>Menjelang tidur</option><option ${c.hard==='Saat bangun/pagi'?'selected':''}>Saat bangun/pagi</option></select></div><div><label>Waktu Bebas Layar Pertama</label><select name="anchor"><option ${c.anchor==='Meja makan'?'selected':''}>Meja makan</option><option ${c.anchor==='30-60 menit sebelum tidur'?'selected':''}>30-60 menit sebelum tidur</option><option ${c.anchor==='Waktu ibadah/kebersamaan'?'selected':''}>Waktu ibadah/kebersamaan</option><option ${c.anchor==='Saat belajar/tugas'?'selected':''}>Saat belajar/tugas</option></select></div><div><label>Aktivitas offline yang biasanya disukai <span class="optional">(opsional)</span></label><input name="fav" value="${esc(c.fav||'')}" placeholder="Menggambar, sepeda, Lego..."></div></div><label>Kebiasaan HP orang tua saat bersama anak</label><select name="parentHabit"><option ${c.parentHabit==='Jarang'?'selected':''}>Jarang</option><option ${c.parentHabit==='Kadang'?'selected':''}>Kadang</option><option ${c.parentHabit==='Sering'?'selected':''}>Sering</option><option ${c.parentHabit==='Belum tahu'?'selected':''}>Belum tahu</option></select><div class="small" style="margin-top:6px">Tidak ada jawaban “baik/buruk”. Ini hanya membantu keluarga melihat konteks bersama.</div><div class="row" style="margin-top:16px"><button class="primary">${c.goal?'Perbarui Family Digital Plan':'Simpan Family Digital Plan'}</button><button type="button" class="ghost" onclick="nav('home')">Kembali ke Dashboard</button></div></form>`;}
function formatDateID(iso){if(!iso)return '-';return new Date(iso).toLocaleDateString('id-ID',{day:'numeric',month:'long',year:'numeric'});} function programEndDate(){if(!state.journeyStartedAt)return null;const d=new Date(state.journeyStartedAt);d.setDate(d.getDate()+13);return d.toISOString();}
function renderJourney(){if(!profileReady())return renderOnboard();const done=completedDays();if(!state.journeyStartedAt){app.innerHTML=`<section class="card hero"><span class="pill">14 hari → 1 output nyata</span><h1>Bangun Family Digital Blueprint</h1><p class="sub">Empat belas hari ini adalah fase uji keluarga. Tidak perlu mengubah semuanya sekaligus—cukup satu langkah kecil per hari.</p><div class="grid three"><div class="card"><h3>Hari 1–4</h3><p>Kenali pola & konteks.</p></div><div class="card"><h3>Hari 5–10</h3><p>Uji aturan, transisi, konten, dan aktivitas.</p></div><div class="card"><h3>Hari 11–14</h3><p>Pilih yang bekerja dan susun sistem keluarga.</p></div></div><div class="notice success" style="margin-top:16px"><b>Begitu tombol di bawah ditekan, Hari 1 langsung terbuka hari ini.</b> Hari berikutnya terbuka sesuai tanggal. Blueprint terbuka pada hari kalender ke-14 walaupun ada hari yang terlewat.</div><br><button class="primary big-cta" onclick="startJourney()">Mulai Hari 1 Sekarang →</button></section>`;return;}const cur=currentProgramDay();const ready=blueprintReady();app.innerHTML=`<div class="row space"><div><h1>14-Day Digital Reset</h1><p class="sub">Mulai ${formatDateID(state.journeyStartedAt)} • Blueprint terbuka ${formatDateID(programEndDate())}</p></div><span class="pill ok">${done}/14 tersimpan</span></div><div class="journey-status"><div><span class="label">Hari program</span><strong>${cur}</strong></div><div><span class="label">Hari yang bisa diisi</span><strong>1–${cur}</strong></div><div><span class="label">Blueprint</span><strong>${ready?'Terbuka':'Hari 14'}</strong></div></div><div class="notice ${ready?'success':''}" style="margin-bottom:14px">${ready?'<b>Fase 14 hari sudah selesai.</b> Semua hari kini terbuka dan Blueprint sudah aktif.':`<b>Hari ${cur} aktif.</b> Hari yang terlewat tetap bisa diisi. Hari berikutnya terbuka otomatis besok.`}</div><div class="grid">${D.journey.map(d=>{const unlocked=dayUnlocked(d[0]);const doneDay=!!state.days[d[0]];const note=state.journeyNotes[d[0]]||'';return `<div class="card day ${doneDay?'done':''} ${unlocked?'':'locked'}"><div class="daynum">${d[0]}</div><div><div class="row principle-day"><h3>${esc(d[1])}</h3><span class="principle-tag">${principleForDay(d[0]).icon} ${principleForDay(d[0]).title}</span></div><p>${esc(d[2])}</p><div class="quote"><b>Aksi:</b> ${esc(d[3])}</div><div class="small" style="margin-top:8px">Basis: ${esc(d[4])}</div>${unlocked?`<label style="margin-top:12px">Catatan untuk Blueprint</label><textarea id="daynote${d[0]}" placeholder="${esc(D.journeyPrompts[d[0]])}">${esc(note)}</textarea><div class="row"><button class="${doneDay?'ghost':'primary'}" onclick="saveDay(${d[0]})">${doneDay?'Perbarui catatan':'Simpan Hari '+d[0]}</button>${doneDay?'<span class="pill ok">✓ Tersimpan</span>':''}</div>`:`<div class="small lock-copy" style="margin-top:12px"><b>Terbuka pada Hari ${d[0]}.</b> Tidak perlu mengerjakannya sekarang.</div>`}</div><div>${doneDay?'✓':unlocked?'○':'🔒'}</div></div>`}).join('')}</div>${ready?'<section class="card hero" style="margin-top:16px"><h2>🎉 Family Digital Blueprint sudah terbuka</h2><p>Blueprint dibuat dari data yang sempat terkumpul. Jika ada hari yang terlewat, lengkapi kapan saja—Blueprint akan ikut diperbarui.</p><button class="primary" onclick="nav(\'blueprint\')">Lihat Family Digital Blueprint</button></section>':''}`;}
let timerInt=null,timerEnd=null;
function startTimer(){const mins=+(document.getElementById('todayMins').value||0);if(!mins)return;timerEnd=Date.now()+mins*60000;clearInterval(timerInt);timerInt=setInterval(updateTimer,250);updateTimer()}
function updateTimer(){const el=document.getElementById('timer');if(!el)return;let left=Math.max(0,timerEnd-Date.now());let m=Math.floor(left/60000),s=Math.floor((left%60000)/1000);el.textContent=`${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`;if(!left){clearInterval(timerInt);el.textContent='SELESAI';}}
function toggleWatch(id){const i=state.savedWatch.indexOf(id); if(i>=0)state.savedWatch.splice(i,1);else state.savedWatch.push(id);save();renderWatch();}
function toggleActivity(name){const i=state.savedActivities.indexOf(name); if(i>=0)state.savedActivities.splice(i,1);else state.savedActivities.push(name);save();renderActivity();}
function renderToday(){if(!profileReady())return renderOnboard(); const c=state.checkup; const age=state.profile.age; const picks=D.watch.filter(w=>age>=w.age_min&&age<=w.age_max).slice(0,3); const acts=D.activities.filter(a=>{let r=a[1];let [lo,hi]=r.split('-').map(Number);return age>=lo&&age<=hi}).slice(0,4); app.innerHTML=`<div class="grid two"><section class="card hero"><h1>Today Mode</h1><p class="sub">Rencanakan satu sesi, bukan “menyerahkan gadget”.</p><label>Durasi yang disepakati hari ini (menit)</label><input id="todayMins" type="number" value="${c.target||30}" min="1"><br><button class="primary" onclick="startTimer()">Mulai Timer</button><div class="timer" id="timer">--:--</div><div class="small">Gunakan timer sebagai pengingat, bukan hukuman.</div></section><section class="card"><h2>Script sebelum mulai</h2><div class="quote"><b>🧭 Tegas tanpa reaktif:</b> “Kita pakai sampai timer selesai. Setelah itu kamu pilih [aktivitas A] atau [aktivitas B].”</div><div class="quote" style="margin-top:10px"><b>🌉 Jembatan keluar layar:</b> “Sebentar lagi selesai. Tunjukkan bagian terakhir yang mau kamu selesaikan, lalu kita lanjut ke kegiatan yang sudah dipilih.”</div><div class="process-praise" style="margin-top:10px"><b>🌱 Setelah aktivitas:</b> komentari proses, misalnya “Tadi kamu mencoba cara lain waktu yang pertama belum berhasil.”</div><h3 style="margin-top:18px">Waktu Bebas Layar Pertama</h3><p>${esc(c.anchor||'Belum ditentukan')}</p><h3>Aktivitas yang biasanya disukai</h3><p>${esc(c.fav||'Belum dicatat')}</p></section></div><h2 style="margin-top:20px">Pilihan tontonan untuk usia ${age}</h2><div class="grid three">${picks.map(w=>watchCard(w,false)).join('')}</div><h2 style="margin-top:20px">Aktivitas sesudah layar</h2><div class="grid two">${acts.map(a=>`<div class="card"><div class="row space"><h3>${esc(a[0])}</h3><span class="pill">${esc(a[2])} mnt</span></div><p>${esc(a[6])}</p></div>`).join('')}</div>`}
function watchCard(w,showSave=true){const saved=state.savedWatch.includes(w.id);const dur=w.minutes?`${w.minutes} mnt`:'durasi cek YouTube';return `<div class="card watch-card"><div class="row space"><span class="pill">${esc(w.language)}</span><span class="pill gray">Preview orang tua disarankan</span></div><h3 style="margin-top:10px">${esc(w.title)}</h3><div class="meta"><span class="pill gray">${w.age_min}-${w.age_max} th</span><span class="pill gray">${esc(dur)}</span>${w.themes.map(t=>`<span class="pill gray">${esc(t)}</span>`).join('')}</div><p>${esc(w.why)}</p><div class="quote"><b>💬 Talk:</b> ${esc(w.talk[0])}<br><b>🌉 Do:</b> ${esc(w.do)}<br><b>🔎 Explore:</b> setelah mencoba, tanyakan “Apa yang kamu perhatikan? Mau mencoba cara lain?”</div><div class="small" style="margin-top:8px">Channel: ${esc(w.channel)}</div><div class="row" style="margin-top:10px"><a target="_blank" href="${w.url}">Buka di YouTube ↗</a>${showSave?`<button class="ghost" onclick="toggleWatch('${w.id}')">${saved?'✓ Tersimpan':'♡ Simpan ke Blueprint'}</button>`:''}</div></div>`}
function renderWatch(){if(!profileReady())return renderOnboard();const age=state.profile.age;const themes=['Semua','Sains & Alam','Sosial-emosional & Karakter','Literasi & Bahasa','Numerasi & Logika','Kebiasaan & Life Skills','Kreativitas & Problem Solving','Nilai & Adab'];const languages=['Semua','Bahasa Indonesia','English'];const ageCount=D.watch.filter(w=>age>=w.age_min&&age<=w.age_max).length;app.innerHTML=`<div class="row space"><div><h1>Boleh Nonton Apa?</h1><p class="sub">Cari video/episode yang sudah ditinjau berdasarkan kriteria kurasi produk—bukan rekomendasi algoritma YouTube.</p></div><span class="pill">${D.watch.length} pilihan di library</span></div><div class="curation-summary"><div><b>${ageCount}</b><span>pilihan cocok untuk usia ${age} tahun</span></div><div><b>2</b><span>bahasa: Indonesia & English</span></div><div><b>7</b><span>kategori tetap</span></div></div><div class="notice">Orang tua tetap disarankan melakukan preview singkat karena isi video/platform dapat berubah. Rentang usia adalah panduan kurasi produk, bukan rating resmi.</div><div class="filters" style="margin-top:14px"><select id="fTheme" onchange="filterWatch()">${themes.map(x=>`<option>${x}</option>`).join('')}</select><select id="fLang" onchange="filterWatch()">${languages.map(x=>`<option>${x}</option>`).join('')}</select><select id="fAge" onchange="filterWatch()"><option value="profile">Untuk usia ${age} tahun</option><option value="all">Semua usia 3-10</option></select><input id="fSearch" oninput="filterWatch()" placeholder="Cari judul, channel, atau tema..."></div><div class="row space watch-result-row"><span id="watchCount" class="small"></span><button class="ghost compact" onclick="resetWatchFilters()">Reset filter</button></div><div id="watchGrid" class="grid two"></div>`;filterWatch();}
function filterWatch(){const theme=document.getElementById('fTheme')?.value||'Semua';const lang=document.getElementById('fLang')?.value||'Semua';const ag=document.getElementById('fAge')?.value||'profile';const q=(document.getElementById('fSearch')?.value||'').toLowerCase();const age=state.profile.age;const items=D.watch.filter(w=>(theme==='Semua'||w.themes.includes(theme))&&(lang==='Semua'||w.language===lang)&&(ag==='all'||(age>=w.age_min&&age<=w.age_max))&&(!q||[w.title,w.channel,w.language,...w.themes].join(' ').toLowerCase().includes(q)));const count=document.getElementById('watchCount');if(count)count.textContent=`${items.length} pilihan cocok`;document.getElementById('watchGrid').innerHTML=items.length?items.map(w=>watchCard(w,true)).join(''):`<div class="card empty" style="grid-column:1/-1"><h3>Belum ada pilihan yang cocok dengan filter ini.</h3><p>Coba tampilkan semua usia/bahasa atau hapus kata pencarian. Kategori tetap dipertahankan.</p><button class="primary" onclick="resetWatchFilters()">Tampilkan semua pilihan</button></div>`;}
function resetWatchFilters(){const t=document.getElementById('fTheme'),l=document.getElementById('fLang'),a=document.getElementById('fAge'),q=document.getElementById('fSearch');if(t)t.value='Semua';if(l)l.value='Semua';if(a)a.value='all';if(q)q.value='';filterWatch();}
function renderActivity(){if(!profileReady())return renderOnboard(); const age=state.profile.age; const acts=D.activities.filter(a=>{let [lo,hi]=a[1].split('-').map(Number);return age>=lo&&age<=hi}); app.innerHTML=`<div class="row space"><div><h1>Habis Nonton Ngapain?</h1><p class="sub">Pilih aktivitas singkat berdasarkan usia dan konteks. Simpan yang cocok agar masuk Blueprint.</p></div><span class="pill">${state.savedActivities.length} tersimpan</span></div><div class="grid two">${acts.map(a=>{const saved=state.savedActivities.includes(a[0]);return `<div class="card"><div class="row space"><h3>${esc(a[0])}</h3><span class="pill">${esc(a[2])} mnt</span></div><p>${esc(a[6])}</p><div class="small">Usia ${esc(a[1])} • ${esc(a[3])} • ${esc(a[5])}</div><div class="process-praise">🌱 Respons proses: sebut usaha, strategi, atau kontribusi anak—bukan hanya “pintar”.</div><button class="ghost" style="margin-top:10px" onclick="toggleActivity('${String(a[0]).replace(/'/g,"\\'")}')">${saved?'✓ Tersimpan':'♡ Simpan ke Blueprint'}</button></div>`}).join('')}</div>`}
function addLog(form){const fd=new FormData(form); state.logs.unshift({date:new Date().toISOString().slice(0,10),planned:+fd.get('planned')||0,actual:+fd.get('actual')||0,content:fd.get('content')||'',period:fd.get('period')||'',warning:fd.get('warning')||'',conflict:fd.get('conflict')||'',after:fd.get('after')||'',note:fd.get('note')||''});save();renderLog();}
function pattern(){if(!state.logs.length)return null;const logs=state.logs;const avgAct=Math.round(logs.reduce((s,l)=>s+(+l.actual||0),0)/logs.length),avgPlan=Math.round(logs.reduce((s,l)=>s+(+l.planned||0),0)/logs.length);const conflicts={};logs.filter(l=>l.conflict!=='Tidak').forEach(l=>conflicts[l.period]=(conflicts[l.period]||0)+1);const risk=Object.entries(conflicts).sort((a,b)=>b[1]-a[1])[0];const acts={};logs.filter(l=>l.after).forEach(l=>acts[l.after]=(acts[l.after]||0)+1);const fav=Object.entries(acts).sort((a,b)=>b[1]-a[1])[0];const warns=logs.filter(l=>l.warning==='Ya'),warnConflict=warns.filter(l=>l.conflict!=='Tidak').length;const noWarn=logs.filter(l=>l.warning==='Tidak'),noWarnConflict=noWarn.filter(l=>l.conflict!=='Tidak').length;return {avgAct,avgPlan,risk:risk&&risk[0],fav:fav&&fav[0],warns:warns.length,warnConflict,noWarn:noWarn.length,noWarnConflict};}
function patternHTML(compact=false){const p=pattern();if(!p)return `<section class="card" ${compact?'style="margin-top:16px"':''}><h2>Pola Keluarga</h2><p class="sub">Belum cukup catatan untuk menampilkan pola. Setelah beberapa log, aplikasi hanya akan merangkum apa yang benar-benar tercatat.</p></section>`;let rows=[`Rata-rata aktual ${p.avgAct} menit dibanding rencana ${p.avgPlan} menit.`,p.risk?`Waktu konflik paling sering pada catatan saat ini: ${p.risk}.`:null,p.fav?`Aktivitas setelah layar yang paling sering dicatat: ${p.fav}.`:null,p.warns?`Dengan warning: ${p.warnConflict} konflik dari ${p.warns} catatan.`:null,p.noWarn?`Tanpa warning: ${p.noWarnConflict} konflik dari ${p.noWarn} catatan.`:null].filter(Boolean);return `<section class="card" ${compact?'style="margin-top:16px"':''}><h2>Pola yang terlihat</h2>${rows.map(x=>`<div class="stat" style="margin-top:8px">${esc(x)}</div>`).join('')}<div class="small" style="margin-top:10px">Deskriptif berdasarkan catatan keluarga; tidak membuktikan sebab-akibat.</div></section>`}
function renderLog(){if(!profileReady())return renderOnboard(); const c=state.checkup; app.innerHTML=`<div class="grid two"><form class="card" onsubmit="event.preventDefault();addLog(this)"><h1>Daily Check-In</h1><p class="sub">Catatan ini adalah bahan Pattern Finder dan Blueprint.</p><div class="grid two"><div><label>Rencana (menit)</label><input name="planned" type="number" value="${c.target||''}"></div><div><label>Aktual (menit)</label><input name="actual" type="number" required></div><div><label>Waktu sesi</label><select name="period"><option>Pagi</option><option>Siang</option><option>Sore</option><option>Malam</option></select></div><div><label>Ada warning sebelum selesai?</label><select name="warning"><option>Ya</option><option>Tidak</option></select></div><div><label>Ada konflik/protes?</label><select name="conflict"><option>Tidak</option><option>Ringan</option><option>Besar</option></select></div><div><label>Konten</label><input name="content" placeholder="Nama video/game"></div></div><label>Aktivitas setelah layar</label><input name="after" placeholder="Contoh: menggambar"><label>Catatan singkat</label><textarea name="note" placeholder="Apa yang bekerja / tidak bekerja?"></textarea><button class="primary">Simpan Check-In</button></form>${patternHTML()}</div><section class="card" style="margin-top:16px"><h2>Riwayat</h2>${state.logs.length?`<table><thead><tr><th>Tanggal</th><th>Rencana/Aktual</th><th>Waktu</th><th>Warning</th><th>Konflik</th><th>Sesudah</th></tr></thead><tbody>${state.logs.map(l=>`<tr><td>${l.date}</td><td>${l.planned}/${l.actual} mnt</td><td>${esc(l.period)}</td><td>${esc(l.warning)}</td><td>${esc(l.conflict)}</td><td>${esc(l.after)}</td></tr>`).join('')}</tbody></table>`:'<p class="small">Belum ada log.</p>'}</section>`}
function blueprintData(){const p=pattern(); const savedW=state.savedWatch.map(id=>D.watch.find(w=>w.id===id)).filter(Boolean); const logActs={};state.logs.filter(l=>l.after).forEach(l=>logActs[l.after]=(logActs[l.after]||0)+1);const topLogActs=Object.entries(logActs).sort((a,b)=>b[1]-a[1]).slice(0,5).map(x=>x[0]);const acts=[...new Set([...state.savedActivities,...topLogActs])].slice(0,10);return {p,savedW,acts};}
function renderBlueprint(){if(!profileReady())return renderOnboard(); if(!blueprintReady()){app.innerHTML=`<section class="card hero"><span class="pill warn">Belum terbuka</span><h1>Family Digital Blueprint</h1><p class="sub">Blueprint adalah hasil nyata yang terbuka pada hari kalender ke-14, bukan bonus terpisah. Ia dibangun dari Check-Up, catatan 14 hari, saved watch list, aktivitas, dan log keluarga.</p><div class="grid two"><div class="card"><h3>Nanti berisi</h3><p>Aturan keluarga • pola yang terlihat • strategi transisi • tontonan personal • aktivitas favorit • parent habit • rencana 30 hari.</p></div><div class="card"><h3>Catatan yang sudah tersimpan</h3><div class="metric">${completedDays()}/14</div><div class="progress"><div style="width:${completedDays()/14*100}%"></div></div></div></div><br><button class="primary" onclick="nav('journey')">Lanjutkan 14 Hari</button></section>`;return;} const {p,savedW,acts}=blueprintData(); const rules=(state.journeyNotes[13]||'').split(/\n|;/).filter(Boolean).slice(0,5); const next=state.journeyNotes[14]||'Pertahankan aturan yang terasa realistis dan lakukan review mingguan.'; app.innerHTML=`<div class="row space"><div><span class="pill ok">Blueprint aktif</span><h1>Family Digital Blueprint</h1><p class="sub">Panduan ini dapat terus diperbarui setelah fase 14 hari selesai.</p></div><button class="primary" onclick="printBlueprint()">Unduh Blueprint PDF</button></div><div class="grid two"><section class="card"><h2>1. Profil & Fokus</h2><p><b>${esc(state.profile.name)}</b> • ${state.profile.age} tahun</p><p>${esc(makePlan())}</p></section><section class="card"><h2>2. Aturan yang Dipertahankan</h2>${rules.length?`<ul>${rules.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:`<p>Waktu Bebas Layar Pertama: <b>${esc(state.checkup.anchor||'-')}</b></p><p>Target saat ini: <b>${state.checkup.target||'-'} menit</b></p>`}</section></div><div class="grid two" style="margin-top:16px"><section class="card"><h2>3. Pola 14 Hari</h2>${p?`<p>Rata-rata aktual: <b>${p.avgAct} menit</b> • Rencana: ${p.avgPlan} menit.</p>${p.risk?`<p>Waktu konflik paling sering: <b>${esc(p.risk)}</b>.</p>`:''}${p.warns?`<p>Dengan warning: ${p.warnConflict}/${p.warns} catatan memiliki konflik.</p>`:''}${p.noWarn?`<p>Tanpa warning: ${p.noWarnConflict}/${p.noWarn} catatan memiliki konflik.</p>`:''}`:'<p>Belum ada cukup daily log. Blueprint tetap bisa digunakan dan diperbarui.</p>'}<div class="small">Pola deskriptif, bukan diagnosis atau bukti sebab-akibat.</div></section><section class="card"><h2>4. Strategi Transisi Keluarga</h2><p><b>Hasil Hari 6:</b> ${esc(state.journeyNotes[6]||'Belum dicatat')}</p><p><b>Script pilihan Hari 12:</b> ${esc(state.journeyNotes[12]||'Belum dicatat')}</p></section></div><section class="card" style="margin-top:16px"><h2>5. Personal Curated Watch List</h2>${savedW.length?`<div class="grid two">${savedW.map(w=>`<div class="watch-card"><a target="_blank" href="${w.url}">${esc(w.title)}</a><div class="small">${esc(w.language)} • ${w.age_min}-${w.age_max} tahun • ${esc(w.themes.join(', '))}</div></div>`).join('')}</div>`:'<p>Belum ada tontonan tersimpan. Buka “Boleh Nonton Apa?” dan simpan pilihan yang cocok.</p>'}</section><section class="card" style="margin-top:16px"><h2>6. Aktivitas Pengganti Favorit</h2>${acts.length?`<div class="row">${acts.map(a=>`<span class="pill gray">${esc(a)}</span>`).join('')}</div>`:'<p>Belum ada aktivitas tersimpan/logged.</p>'}</section><div class="grid two" style="margin-top:16px"><section class="card"><h2>7. Parent Digital Habit</h2><p>Baseline: <b>${esc(state.checkup.parentHabit||'-')}</b></p><p>Catatan Hari 11: ${esc(state.journeyNotes[11]||'Belum dicatat')}</p></section><section class="card"><h2>8. Rencana 30 Hari Berikutnya</h2><p>${esc(next)}</p></section></div><section class="card" style="margin-top:16px"><h2>9. Kompas 4 Prinsip Keluarga</h2><p class="sub">Blueprint bukan hanya rangkuman durasi. Empat prinsip ini menjadi cara keluarga membaca dan menyesuaikan rutinitas setelah Hari 14.</p><div class="principle-grid"><div class="principle-card"><div class="principle-icon">🧭</div><div><b>Tegas tanpa reaktif</b><p>${esc(state.journeyNotes[6]||state.journeyNotes[12]||'Pilih satu script batas yang singkat dan konsisten untuk diuji minggu ini.')}</p></div></div><div class="principle-card"><div class="principle-icon">🌉</div><div><b>Teknologi → pengalaman nyata</b><p>${acts.length?'Aktivitas nyata yang sudah muncul di keluarga: '+esc(acts.slice(0,3).join(', '))+'.':'Pilih satu aktivitas sederhana yang siap dilakukan setelah layar.'}</p></div></div><div class="principle-card"><div class="principle-icon">🔎</div><div><b>Eksplorasi</b><p>${esc(state.journeyNotes[10]||'Sesudah layar, gunakan satu pertanyaan observasi dan beri ruang anak mencoba.')}</p></div></div><div class="principle-card"><div class="principle-icon">🌱</div><div><b>Rasa mampu</b><p>${esc(state.journeyNotes[14]||'Soroti usaha, strategi, pilihan, dan kontribusi anak saat melakukan aktivitas nyata.')}</p></div></div></div></section><section class="card hero" style="margin-top:16px"><h2>Maintenance Mode</h2><p>Setelah 14 hari, produk tidak selesai. Gunakan siklus <b>Plan → Use → Log → Learn → Adjust</b>.</p><div class="grid three"><button class="ghost" onclick="nav('weekly')">🧠 Weekly Family Review</button><button class="ghost" onclick="nav('coach')">✨ AI Family Coach</button><button class="ghost" onclick="nav('explore')">🌱 Explore After Screen</button></div><label style="margin-top:14px">Catatan review minggu ini</label><textarea id="weeklyNote">${esc(state.maintenance.weeklyNote||'')}</textarea><button class="primary" onclick="state.maintenance.weeklyNote=document.getElementById('weeklyNote').value;save();alert('Review mingguan tersimpan')">Simpan Review Mingguan</button></section>`}

function familyContextText(){
  if(!profileReady()) return 'Profil keluarga belum diisi.';
  const p=pattern();
  const savedW=state.savedWatch.map(id=>D.watch.find(w=>w.id===id)).filter(Boolean).slice(0,8);
  const notes=Object.entries(state.journeyNotes).filter(([k,v])=>String(v||'').trim()).slice(-6);
  const recent=state.logs.slice(0,7);
  const lines=[
    'KONTEKS KELUARGA — Gadget Tanpa Drama',
    'Nama/panggilan anak: '+(state.profile.name||'-'),
    'Usia: '+(state.profile.age||'-')+' tahun',
    'Caregiver: '+(state.profile.caregiver||'Orang tua'),
    'Tujuan utama: '+(state.checkup.goal||'-'),
    'Momen paling sulit: '+(state.checkup.hard||'-'),
    'Waktu bebas layar: '+(state.checkup.anchor||'-'),
    'Target keluarga saat ini: '+(state.checkup.target||'-')+' menit/hari',
    'Aktivitas offline yang disukai: '+(state.checkup.fav||'-'),
    'Kebiasaan HP orang tua: '+(state.checkup.parentHabit||'-'),
    p?'Pola tercatat: rata-rata aktual '+p.avgAct+' menit; rencana '+p.avgPlan+' menit; waktu konflik paling sering '+(p.risk||'belum terlihat')+'.':'Pola tercatat: belum cukup log.',
    'Tontonan tersimpan: '+(savedW.length?savedW.map(w=>w.title).join(' | '):'belum ada'),
    'Catatan 14 hari terbaru: '+(notes.length?notes.map(([k,v])=>'Hari '+k+': '+v).join(' | '):'belum ada'),
    'Log 7 sesi terbaru: '+(recent.length?recent.map(l=>l.date+' '+l.period+', '+l.actual+' menit, warning '+l.warning+', konflik '+l.conflict+', sesudah '+(l.after||'-')).join(' | '):'belum ada')
  ];
  return lines.join('\n');
}
function coachPrompt(mode){
  const base=familyContextText();
  const guard='Anda adalah AI Family Coach untuk produk Gadget Tanpa Drama. Semua saran harus melewati empat prinsip: (1) Tegas tanpa reaktif—batas jelas tanpa mempermalukan; (2) Teknologi ke pengalaman nyata—selalu cari jembatan dari layar ke kehidupan nyata; (3) Eksplorasi—beri ruang anak mengamati, bertanya, mencoba, dan menceritakan; (4) Rasa mampu—soroti usaha, strategi, pilihan, dan kontribusi anak. Gunakan hanya konteks keluarga di bawah dan prinsip umum pengasuhan non-klinis. Jangan mendiagnosis, jangan menyimpulkan penyebab psikologis, jangan menjanjikan perubahan perilaku. Bedakan fakta catatan keluarga dari dugaan. Beri saran singkat, realistis, tidak menghakimi.';
  const task={
    transition:'Situasi: anak sulit berhenti dari gadget. Berikan: (1) satu kalimat yang bisa diucapkan orang tua sekarang, (2) dua langkah transisi berikutnya, (3) hal yang sebaiknya dihindari, (4) satu aktivitas pengganti sesuai usia.',
    conflict:'Situasi: terjadi konflik/protes saat aturan gadget ditegakkan. Berikan respons tegas dan hangat, maksimal 5 langkah, tanpa hukuman berlebihan.',
    plan:'Buat rencana digital keluarga untuk 7 hari berikutnya berdasarkan pola yang benar-benar tercatat. Pilih hanya 1 eksperimen utama agar mudah diuji.',
    review:'Ringkas apa yang tampak bekerja dan belum bekerja dari log keluarga. Gunakan bahasa deskriptif seperti “terlihat”, “pada catatan ini”, bukan sebab-akibat.'
  }[mode]||'Bantu orang tua mengambil langkah berikutnya yang konkret.';
  return guard+'\n\n'+base+'\n\nTUGAS:\n'+task+'\n\nFormat jawaban: Yang terlihat / Prinsip GTD yang dipakai / Yang bisa dilakukan sekarang / Kalimat yang bisa dipakai / Jembatan ke pengalaman nyata / Hal yang perlu diamati berikutnya.';
}
async function copyText(t){try{await navigator.clipboard.writeText(t);toast('✓ Konteks AI disalin.');return true}catch(e){const ta=document.createElement('textarea');ta.value=t;document.body.appendChild(ta);ta.select();document.execCommand('copy');ta.remove();toast('✓ Konteks AI disalin.');return true}}
function openGemini(mode){const prompt=coachPrompt(mode);copyText(prompt);setTimeout(()=>window.open('https://gemini.google.com/app','_blank','noopener'),180);}
function renderCoach(){
  if(!profileReady())return renderOnboard();
  app.innerHTML=`<div class="row space"><div><span class="pill ai">AI tanpa API key</span><h1>AI Family Coach</h1><p class="sub">Aplikasi menyiapkan konteks keluarga; Gemini membantu mempersonalisasi langkah berikutnya. Anda tetap memutuskan apa yang cocok.</p></div></div>
  <section class="card hero"><h2>Apa yang sedang terjadi?</h2><div class="ai-grid">
  <button class="ai-action" onclick="openGemini('transition')"><b>⏹️ Susah berhenti gadget</b><span>Buat script + jembatan transisi</span></button>
  <button class="ai-action" onclick="openGemini('conflict')"><b>🌪️ Lagi ada konflik</b><span>Respons tegas tanpa mempermalukan</span></button>
  <button class="ai-action" onclick="openGemini('review')"><b>🔎 Baca pola keluargaku</b><span>Ringkas log tanpa diagnosis</span></button>
  <button class="ai-action" onclick="openGemini('plan')"><b>🗓️ Rencana 7 hari</b><span>Pilih satu eksperimen berikutnya</span></button>
  </div><div class="notice" style="margin-top:14px"><b>Cara kerja:</b> tombol menyalin konteks keluarga + instruksi aman, lalu membuka Gemini. Tempelkan teks di sana. Produk ini tidak menyimpan API key dan tidak mengirim data otomatis ke model AI.</div></section>
  <section class="card" style="margin-top:16px"><h2>Preview konteks yang akan dibawa</h2><pre class="context-preview">${esc(familyContextText())}</pre><button class="ghost" onclick="copyText(coachPrompt('review'))">Salin konteks + instruksi</button></section>
  <section class="card" style="margin-top:16px"><h2>Batas AI</h2><p>AI dipakai sebagai <b>personalizer dan summarizer</b>, bukan sumber tunggal nasihat parenting. AI tidak boleh mendiagnosis kecanduan, ADHD, gangguan emosi, atau menjelaskan “akar trauma” anak dari log ini.</p></section>`;
}
function saveWeeklyReview(form){
  const fd=new FormData(form);
  const item={date:new Date().toISOString().slice(0,10),worked:String(fd.get('worked')||'').trim(),hard:String(fd.get('hard')||'').trim(),principle:String(fd.get('principle')||'').trim(),experiment:String(fd.get('experiment')||'').trim()};
  if(!item.worked&&!item.hard&&!item.experiment){toast('Isi minimal satu bagian review.','warn');return}
  state.maintenance.weeklyReviews.unshift(item);
  state.maintenance.nextExperiment=item.experiment||state.maintenance.nextExperiment||'';
  save();renderWeekly();setTimeout(()=>toast('✓ Weekly Review tersimpan.'),0);
}
function renderWeekly(){
  if(!profileReady())return renderOnboard();
  const p=pattern();const reviews=state.maintenance.weeklyReviews||[];
  app.innerHTML=`<div class="row space"><div><span class="pill ok">Maintenance Loop</span><h1>Weekly Family Review</h1><p class="sub">Sesudah 14 hari, keluarga terus memakai siklus Plan → Use → Log → Learn → Adjust.</p></div><button class="primary" onclick="openGemini('review')">✨ Analisis dengan AI</button></div>
  <div class="grid three"><div class="card"><div class="label">Log tersimpan</div><div class="metric">${state.logs.length}</div></div><div class="card"><div class="label">Review mingguan</div><div class="metric">${reviews.length}</div></div><div class="card"><div class="label">Eksperimen aktif</div><div class="small">${esc(state.maintenance.nextExperiment||'Belum dipilih')}</div></div></div>
  ${patternHTML(true)}
  <form class="card" style="margin-top:16px" onsubmit="event.preventDefault();saveWeeklyReview(this)"><h2>Review minggu ini</h2><label>Apa yang terasa bekerja?</label><textarea name="worked" placeholder="Contoh: warning 10 menit membuat transisi lebih mudah pada beberapa sesi"></textarea><label>Apa yang masih sulit?</label><textarea name="hard" placeholder="Contoh: sesi malam masih sering molor"></textarea><label>Prinsip yang paling ingin dilatih minggu depan</label><select name="principle"><option>Tegas tanpa reaktif</option><option>Teknologi → pengalaman nyata</option><option>Eksplorasi</option><option>Rasa mampu</option></select><label>Satu eksperimen untuk 7 hari berikutnya</label><textarea name="experiment" placeholder="Contoh: pindahkan screen time sebelum makan malam dan siapkan aktivitas sesudahnya"></textarea><button class="primary">Simpan Review Mingguan</button></form>
  <section class="card" style="margin-top:16px"><h2>Riwayat review</h2>${reviews.length?reviews.map(r=>`<div class="weekly-item"><b>${esc(r.date)}</b><p><b>Bekerja:</b> ${esc(r.worked||'-')}</p><p><b>Masih sulit:</b> ${esc(r.hard||'-')}</p><p><b>Prinsip fokus:</b> ${esc(r.principle||'-')}</p><p><b>Eksperimen berikutnya:</b> ${esc(r.experiment||'-')}</p></div>`).join(''):'<p class="small">Belum ada review mingguan.</p>'}</section>`;
}
function renderExplore(){
  if(!profileReady())return renderOnboard();
  const age=state.profile.age;
  const selected=state.savedWatch.map(id=>D.watch.find(w=>w.id===id)).filter(Boolean);
  const watch=selected[0]||D.watch.find(w=>age>=w.age_min&&age<=w.age_max);
  const acts=D.activities.filter(a=>{const r=a[1].split('-').map(Number);return age>=r[0]&&age<=r[1]}).slice(0,6);
  app.innerHTML=`<div class="row space"><div><span class="pill">Watch → Talk → Do → Explore</span><h1>Explore After Screen</h1><p class="sub">Tujuannya bukan sekadar mengganti gadget, tetapi menjembatani layar ke interaksi, bermain, mencoba, dan rasa mampu.</p></div></div>
  ${watch?`<section class="card hero"><div class="label">Mulai dari tontonan</div><h2>${esc(watch.title)}</h2><p>${esc(watch.why)}</p><div class="explore-steps"><div><b>1. Watch</b><span>Tonton dengan tujuan yang jelas.</span></div><div><b>2. Talk</b><span>${esc(watch.talk[0]||'Apa yang paling kamu ingat?')}</span></div><div><b>3. Do</b><span>${esc(watch.do)}</span></div><div><b>4. Explore</b><span>Biarkan anak mencoba, mengubah cara, dan menceritakan temuannya.</span></div></div></section>`:''}
  <section class="card" style="margin-top:16px"><h2>Misi eksplorasi untuk usia ${age}</h2><div class="grid two">${acts.map(a=>`<div class="mission"><div class="row space"><b>${esc(a[0])}</b><span class="pill gray">${esc(a[2])} mnt</span></div><p>${esc(a[6])}</p><div class="process-praise">Coba respons proses: “Aku lihat kamu mencoba cara lain waktu yang pertama belum berhasil.”</div></div>`).join('')}</div></section>
  <section class="card" style="margin-top:16px"><h2>Kompas 4 Prinsip</h2><p><b>🧭 Tegas tanpa reaktif.</b> Batas tetap jelas, tetapi tujuan disiplin adalah mengajar, bukan menakut-nakuti.</p><p><b>🌉 Teknologi → pengalaman nyata.</b> Screen time dipakai sengaja lalu disambungkan ke permainan, percakapan, gerak, atau kegiatan nyata.</p><p><b>🔎 Eksplorasi.</b> Anak diberi ruang mengamati, bertanya, memprediksi, mencoba, mengubah cara, dan menceritakan temuannya.</p><p><b>🌱 Bangun rasa mampu.</b> Fokus pada usaha, strategi, pilihan, dan kontribusi; bukan hanya hasil sempurna atau kepatuhan.</p><div class="small">Prinsip editorial ini dirumuskan ulang dari panduan pengasuhan/perkembangan yang ditinjau tim produk, termasuk materi pembelajaran berlisensi milik pembuat produk; bukan salinan materi kursus.</div></section>`;
}

function renderSources(){app.innerHTML=`<h1>Sumber & Batasan</h1><p class="sub">Produk edukatif untuk membantu keluarga mengelola rutinitas digital. Bukan diagnosis, terapi, atau alat penilaian perkembangan.</p><div class="grid two"><div class="card"><h2>Prinsip kurasi tontonan</h2><p>Kategori dipertahankan tetap, pilihan disusun per video/episode, dan orang tua tetap disarankan melakukan preview karena isi platform dapat berubah dari waktu ke waktu.</p></div><div class="card"><h2>Library saat ini</h2><div class="metric">${D.watch.length}</div><p>video/episode Bahasa Indonesia & English dalam berbagai tema.</p></div></div><section class="card" style="margin-top:16px"><h2>Sumber kerangka</h2><table><thead><tr><th>ID</th><th>Sumber</th><th>Dipakai untuk</th></tr></thead><tbody>${D.sources.map(s=>`<tr><td>${esc(s.id)}</td><td><a href="${s.url}" target="_blank">${esc(s.name)}</a></td><td>${esc(s.use)}</td></tr>`).join('')}</tbody></table></section><section class="card" style="margin-top:16px"><h2>Batas penggunaan</h2><p>Insight pola hanya merangkum catatan keluarga. Aplikasi tidak menentukan penyebab psikologis perilaku anak, tidak mendiagnosis kecanduan/ADHD/gangguan lain, dan tidak menjanjikan tantrum hilang dalam 14 hari.</p></section>`}
function safeFileName(s){return String(s||'keluarga').trim().replace(/[^a-z0-9_-]+/gi,'-').replace(/^-+|-+$/g,'').slice(0,40)||'keluarga';}
function backup(){state.meta=state.meta||{};state.meta.lastBackupAt=new Date().toISOString();save();const envelope={magic:BACKUP_MAGIC,version:BACKUP_VERSION,exportedAt:new Date().toISOString(),product:'Gadget Tanpa Drama',state};const blob=new Blob([JSON.stringify(envelope)],{type:'application/octet-stream'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`GTD-${safeFileName(state.profile?.name)}-${new Date().toISOString().slice(0,10)}.gtd`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500);setTimeout(()=>toast('✓ Perjalanan tersimpan. Simpan file ini di tempat yang mudah ditemukan.'),80);}
function printReport(){if(blueprintReady())return printBlueprint();if(!profileReady()){alert('Isi profil terlebih dahulu.');return;}const done=completedDays();const pp=pattern();const patterns=pp?[`Rata-rata aktual ${pp.avgAct} menit (rencana ${pp.avgPlan} menit).`,pp.risk?`Waktu konflik tertinggi pada catatan saat ini: ${pp.risk}.`:null,pp.fav?`Aktivitas setelah layar yang paling sering dicatat: ${pp.fav}.`:null].filter(Boolean):[];const html=`<!doctype html><html><head><meta charset="utf-8"><title>Laporan Gadget Tanpa Drama</title><style>body{font-family:Arial,sans-serif;color:#1f2937;padding:30px;max-width:850px;margin:auto}h1,h2{color:#3730a3}.box{border:1px solid #e5e7eb;border-radius:14px;padding:16px;margin:14px 0}.small{font-size:12px;color:#6b7280}</style></head><body><h1>Laporan Sementara — Gadget Tanpa Drama</h1><div class="box"><h2>Progress menuju Blueprint</h2><p>${done}/14 hari selesai.</p></div><div class="box"><h2>Family Digital Plan</h2><p>${esc(makePlan())}</p></div><div class="box"><h2>Pola sementara</h2>${patterns.length?'<ul>'+patterns.map(x=>`<li>${esc(x)}</li>`).join('')+'</ul>':'<p>Belum ada cukup data.</p>'}</div><p class="small">Setelah Hari 14, laporan utama berubah menjadi Family Digital Blueprint.</p></body></html>`;const w=window.open('','_blank');w.document.write(html);w.document.close();w.focus();setTimeout(()=>w.print(),250)}
function printBlueprint(){const {p,savedW,acts}=blueprintData();const rules=(state.journeyNotes[13]||'').split(/\n|;/).filter(Boolean).slice(0,5);const next=state.journeyNotes[14]||'Pertahankan aturan yang realistis dan lakukan review mingguan.';const html=`<!doctype html><html><head><meta charset="utf-8"><title>Family Digital Blueprint</title><style>body{font-family:Arial,sans-serif;color:#1f2937;padding:28px;max-width:900px;margin:auto}h1{color:#312e81}h2{color:#4338ca;margin-bottom:6px}.box{border:1px solid #e5e7eb;border-radius:14px;padding:15px;margin:12px 0}.pill{display:inline-block;background:#eef2ff;color:#4338ca;padding:5px 9px;border-radius:999px;margin:3px;font-size:12px}.small{font-size:12px;color:#6b7280}a{color:#4338ca}</style></head><body><h1>Family Digital Blueprint</h1><p class="small">Gadget Tanpa Drama • dibuat dari perjalanan 14 hari keluarga</p><div class="box"><h2>Profil & Fokus</h2><p><b>${esc(state.profile.name)}</b> (${state.profile.age} tahun)</p><p>${esc(makePlan())}</p></div><div class="box"><h2>Aturan Keluarga</h2>${rules.length?'<ul>'+rules.map(x=>`<li>${esc(x)}</li>`).join('')+'</ul>':`<p>Waktu Bebas Layar Pertama: ${esc(state.checkup.anchor||'-')}<br>Target saat ini: ${state.checkup.target||'-'} menit</p>`}</div><div class="box"><h2>Pola yang Terlihat</h2>${p?`<p>Rata-rata aktual ${p.avgAct} menit; rencana ${p.avgPlan} menit.</p>${p.risk?`<p>Waktu konflik paling sering: ${esc(p.risk)}.</p>`:''}${p.warns?`<p>Dengan warning: ${p.warnConflict}/${p.warns} catatan konflik.</p>`:''}${p.noWarn?`<p>Tanpa warning: ${p.noWarnConflict}/${p.noWarn} catatan konflik.</p>`:''}`:'<p>Belum cukup log.</p>'}</div><div class="box"><h2>Strategi Transisi</h2><p>${esc(state.journeyNotes[6]||'Belum dicatat')}</p><p>${esc(state.journeyNotes[12]||'Belum dicatat')}</p></div><div class="box"><h2>Personal Curated Watch List</h2>${savedW.length?'<ul>'+savedW.map(w=>`<li><a href="${w.url}">${esc(w.title)}</a> — ${esc(w.language)}; ${w.age_min}-${w.age_max} th</li>`).join('')+'</ul>':'<p>Belum ada tontonan tersimpan.</p>'}</div><div class="box"><h2>Aktivitas Pengganti Favorit</h2>${acts.length?acts.map(a=>`<span class="pill">${esc(a)}</span>`).join(''):'<p>Belum ada aktivitas tersimpan.</p>'}</div><div class="box"><h2>Parent Digital Habit</h2><p>${esc(state.journeyNotes[11]||state.checkup.parentHabit||'-')}</p></div><div class="box"><h2>Rencana 30 Hari Berikutnya</h2><p>${esc(next)}</p></div><div class="box"><h2>Kompas 4 Prinsip</h2><p><b>Tegas tanpa reaktif:</b> batas jelas, respons tetap tenang.</p><p><b>Teknologi → pengalaman nyata:</b> layar selalu punya jembatan ke percakapan, gerak, bermain, atau tugas nyata.</p><p><b>Eksplorasi:</b> anak diberi ruang mengamati, bertanya, mencoba, dan bercerita.</p><p><b>Rasa mampu:</b> orang tua menyoroti usaha, strategi, pilihan, dan kontribusi.</p></div><p class="small">Pola bersifat deskriptif dari catatan keluarga, bukan diagnosis atau bukti sebab-akibat. Blueprint dapat diperbarui setelah review mingguan.</p></body></html>`;const w=window.open('','_blank');w.document.write(html);w.document.close();w.focus();setTimeout(()=>w.print(),250)}
function normalizeState(s){s=s||{};s.profile=s.profile||{};s.checkup=s.checkup||{};s.days=s.days||{};s.journeyNotes=s.journeyNotes||{};s.logs=s.logs||[];s.parentChecks=s.parentChecks||[];s.savedWatch=s.savedWatch||[];s.savedActivities=s.savedActivities||[];s.maintenance=s.maintenance||{};s.maintenance.weeklyNote=s.maintenance.weeklyNote||'';s.maintenance.weeklyReviews=s.maintenance.weeklyReviews||[];s.maintenance.nextExperiment=s.maintenance.nextExperiment||'';s.meta=s.meta||{};if(!s.meta.familyId)s.meta.familyId=(globalThis.crypto&&crypto.randomUUID?crypto.randomUUID():String(Date.now()));return s;}
function importData(inp){const f=inp.files[0];if(!f)return;const r=new FileReader();r.onload=()=>{try{const parsed=JSON.parse(r.result);let restored;if(parsed&&parsed.magic===BACKUP_MAGIC&&parsed.state){restored=parsed.state}else if(parsed&&parsed.profile){restored=parsed}else{throw new Error('format')}if(!confirm('Pulihkan perjalanan dari file ini? Data yang sekarang ada di perangkat ini akan diganti.'))return;state=normalizeState(restored);save();nav('home');setTimeout(()=>toast('✓ Perjalanan berhasil dipulihkan.'),0)}catch(e){alert('File perjalanan tidak dikenali. Pilih file perjalanan yang dibuat dari Gadget Tanpa Drama.')}};r.readAsText(f);inp.value='';}
function renderData(){const last=formatDateTimeID(state.meta?.lastBackupAt);app.innerHTML=`<div class="row space"><div><h1>Data & Perangkat</h1><p class="sub">Data keluarga tetap di browser ini. Tidak ada login, email, atau database cloud.</p></div><span class="pill ${state.meta?.lastBackupAt?'ok':'warn'}">Backup: ${state.meta?.lastBackupAt?'sudah':'belum'}</span></div><div class="grid two"><section class="card"><h2>Simpan Perjalanan</h2><p>Buat salinan progres agar aman jika browser terhapus atau ingin pindah perangkat.</p><div class="small">Terakhir disimpan: <b>${last}</b></div><br><button class="primary" onclick="backup()">Simpan Perjalanan</button><div class="small" style="margin-top:8px">Browser akan mengunduh satu file perjalanan. Tidak perlu membukanya.</div></section><section class="card"><h2>Pulihkan Perjalanan</h2><p>Pilih file perjalanan yang pernah disimpan. Seluruh progres akan kembali ke aplikasi ini.</p><label class="file-label">Pilih File Perjalanan<input type="file" accept=".gtd,application/json" onchange="importData(this)"></label></section></div><section class="card" style="margin-top:16px"><h2>Kalau ganti HP/laptop</h2><div class="step-list"><div class="step-item">Di perangkat lama tekan <b>Simpan Perjalanan</b>.</div><div class="step-item">Kirim file hasil unduhan ke perangkat baru.</div><div class="step-item">Buka link Gadget Tanpa Drama di perangkat baru, lalu tekan <b>Pulihkan Perjalanan</b>.</div></div></section><section class="card" style="margin-top:16px"><h2>File perjalanan ≠ PDF</h2><p><b>File perjalanan</b> dipakai aplikasi untuk mengembalikan progres. <b>PDF</b> adalah laporan/Blueprint yang dibaca manusia.</p></section><section class="card" style="margin-top:16px"><h2>Privasi lokal</h2><p>Data rutinitas keluarga tidak dikirim ke server produk ini. Data tetap berada di browser sampai Anda menghapus data browser atau mereset aplikasi.</p><button class="ghost danger" onclick="if(confirm('Hapus semua data perjalanan dari perangkat ini? Tindakan ini tidak bisa dibatalkan kecuali Anda punya file perjalanan.')){localStorage.removeItem(KEY);location.reload()}">Reset semua data</button></section>`;}
function render(view){({home:renderHome,checkup:renderCheckup,journey:renderJourney,blueprint:renderBlueprint,today:renderToday,watch:renderWatch,activity:renderActivity,log:renderLog,coach:renderCoach,weekly:renderWeekly,explore:renderExplore,data:renderData,sources:renderSources}[view]||renderHome)()}
